fn array_split(a: Vec<i32>) -> (Vec<i32>, Vec<i32>) {
    // Determine split point: floor(n/2)
    let mid = a.len() / 2;
    // Use `split_off` to take elements from `mid` to end into a new Vec.
    // After this, `a` contains elements [0..mid) and `second` contains [mid..n)
    let mut first = a;
    let second = first.split_off(mid);
    (first, second)
}

